head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil05105";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — stockDuty, param.listProcsStatCd
// TODO Stage2: 세션 키 실환경 확인(회신 11항 · user-info 계약에 없는 키) — session.user.corpUsrTpCd

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil05105.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_27", fn: function(){ return (!(String(((dma_pageContext.get("stockDuty") ?? "")) == null ? '' : ((dma_pageContext.get("stockDuty") ?? ""))).length === 0)); } }, { id: "tr_28", fn: function(){ return (!(String(((dma_pageContext.get("stockDuty") ?? "")) == null ? '' : ((dma_pageContext.get("stockDuty") ?? ""))).length === 0)); } }, { id: "tr_35", fn: function(){ return (!(String(((dma_pageContext.get("stockDuty") ?? "")) == null ? '' : ((dma_pageContext.get("stockDuty") ?? ""))).length === 0)); } }, { id: "tr_51", fn: function(){ return (!(String(((dma_pageContext.get("stockDuty") ?? "")) == null ? '' : ((dma_pageContext.get("stockDuty") ?? ""))).length === 0)); } }, { id: "tr_58", fn: function(){ return (!(String(((dma_pageContext.get("stockDuty") ?? "")) == null ? '' : ((dma_pageContext.get("stockDuty") ?? ""))).length === 0)); } }, { id: "tr_66", fn: function(){ return (!(String(((dma_pageContext.get("stockDuty") ?? "")) == null ? '' : ((dma_pageContext.get("stockDuty") ?? ""))).length === 0)); } }, { id: "tr_89", fn: function(){ return (!(String(((dma_pageContext.get("stockDuty") ?? "")) == null ? '' : ((dma_pageContext.get("stockDuty") ?? ""))).length === 0)); } }, { id: "c_otherwise_93", fn: function(){ return (!((!(String(((dma_pageContext.get("stockDuty") ?? "")) == null ? '' : ((dma_pageContext.get("stockDuty") ?? ""))).length === 0)))); } }, { id: "if_corpUsrTpCd", fn: function(){ return ($c.session.getUserInfo("corpUsrTpCd") ==='62'); } }, { id: "if_corpUsrTpCd_2", fn: function(){ return ($c.session.getUserInfo("corpUsrTpCd") ==='22'); } }, { id: "btn_delete", fn: function(){ return (! (String(((dma_pageContext.get("listProcsStatCd") ?? "")) == null ? '' : ((dma_pageContext.get("listProcsStatCd") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_bzProcsNo", fn: function () { return String((dma_pageContext.get("bzProcsNo") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.onload();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05105.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_stkoptDutyTotGrntShrs_onclick
 * @description ipt_stkoptDutyTotGrntShrs 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_stkoptDutyTotGrntShrs_onclick = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        selfVar.select()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05105.ipt_stkoptDutyTotGrntShrs_onclick' }); }
};

/**
 * @method
 * @name ipt_stkoptDutyTotGrntShrs_onkeyup
 * @description ipt_stkoptDutyTotGrntShrs 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_stkoptDutyTotGrntShrs_onkeyup = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        (selfVar.value = $c.num.formatNumber(selfVar.value));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05105.ipt_stkoptDutyTotGrntShrs_onkeyup' }); }
};

/**
 * @method
 * @name slc_prtdepoIdSelect_onchange
 * @description slc_prtdepoIdSelect 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_prtdepoIdSelect_onchange = async function(e){
    try {
        await scwin.selectChange($c.util.getComponent("slc_prtdepoIdSelect"))

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05105.slc_prtdepoIdSelect_onchange' }); }
};

/**
 * @method
 * @name ipt_stkoptDutyTotGrntShrs_2_onclick
 * @description ipt_stkoptDutyTotGrntShrs_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_stkoptDutyTotGrntShrs_2_onclick = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        selfVar.select()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05105.ipt_stkoptDutyTotGrntShrs_2_onclick' }); }
};

/**
 * @method
 * @name ipt_stkoptDutyTotGrntShrs_2_onkeyup
 * @description ipt_stkoptDutyTotGrntShrs_2 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_stkoptDutyTotGrntShrs_2_onkeyup = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        (selfVar.value = $c.num.formatNumber(selfVar.value));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05105.ipt_stkoptDutyTotGrntShrs_2_onkeyup' }); }
};

/**
 * @method
 * @name btn_delete_onclick
 * @description 「삭제」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_delete_onclick = async function(e){
    try {
        await scwin.deleteRegisterReq()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05105.btn_delete_onclick' }); }
};

/**
 * @method
 * @name btn_cancel_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_cancel_onclick = function(e){
    try {
        scwin.cancel()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05105.btn_cancel_onclick' }); }
};

/**
 * @method
 * @name btn_register_onclick
 * @description 「저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_register_onclick = async function(e){
    try {
        await scwin.register()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05105.btn_register_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_register
 * @description register 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_register = async function () {
    const sbmOptions = {
        id: "tx_fn_register",
        method: "post",
        action: "/list/stockDutyPopup.do",
        ref: "dma_registerReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_delete
 * @description delete 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_delete = async function () {
    const sbmOptions = {
        id: "tx_fn_delete",
        method: "post",
        action: "/list/stockDutyPopup.do",
        ref: "dma_deleteReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name onload
 * @description onload 처리
 * @returns {void}
 * @hidden N
 */
scwin.onload = function () {
    form = (document.stockDutyForm || { elements: [] });
};

/**
 * @method
 * @name validate
 * @description validate 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.validate = async function () {
    if (($c.util.getComponent('ipt_nm').getValue() == null ? '' : String($c.util.getComponent('ipt_nm').getValue())) === '') {
        await $c.win.alert("대상자를 입력하십시요.");
        $c.util.getComponent("ipt_nm").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
    if (($c.util.getComponent('ipt_encrypResdbzRegNo').getValue() == null ? '' : String($c.util.getComponent('ipt_encrypResdbzRegNo').getValue())) === '') {
        await $c.win.alert("생년월일/사업자번호/외국인번호를 입력하십시요.");
        $c.util.getComponent("ipt_encrypResdbzRegNo").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
    if (($c.util.getComponent('cal_stkoptDutyResolDd').getValue() == null ? '' : String($c.util.getComponent('cal_stkoptDutyResolDd').getValue())) === '') {
        await $c.win.alert("부여결의일을 입력하십시요.");
        $c.util.getComponent("cal_stkoptDutyResolDd").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
    if (($c.util.getComponent('ipt_stkoptDutyTotGrntShrs').getValue() == null ? '' : String($c.util.getComponent('ipt_stkoptDutyTotGrntShrs').getValue())) === '') {
        await $c.win.alert("총 부여주식수를 입력하십시요.");
        $c.util.getComponent("ipt_stkoptDutyTotGrntShrs").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
    if (($c.util.getComponent('cal_stkoptDutyExerStartDd').getValue() == null ? '' : String($c.util.getComponent('cal_stkoptDutyExerStartDd').getValue())) === '') {
        await $c.win.alert("행사기간 시작일을 입력하십시요.");
        $c.util.getComponent("cal_stkoptDutyExerStartDd").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
    if (($c.util.getComponent('cal_stkoptDutyExerEndDd').getValue() == null ? '' : String($c.util.getComponent('cal_stkoptDutyExerEndDd').getValue())) === '') {
        await $c.win.alert("행사기간 만료일을 입력하십시요.");
        $c.util.getComponent("cal_stkoptDutyExerEndDd").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
    if (($c.util.getComponent('cal_stkoptDutyExerStartDd').getValue() == null ? '' : String($c.util.getComponent('cal_stkoptDutyExerStartDd').getValue())) !== '' && ($c.util.getComponent('cal_stkoptDutyExerEndDd').getValue() == null ? '' : String($c.util.getComponent('cal_stkoptDutyExerEndDd').getValue())) !== '') {
        if ($c.util.getComponent('cal_stkoptDutyExerStartDd').getValue()> $c.util.getComponent('cal_stkoptDutyExerEndDd').getValue()) {
            await $c.win.alert("행사기간 시작일이 행사기간 만료일보다 이후 일자 입니다.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return false;
        }
    }
    if (($c.util.getComponent('cal_prtdepoEndDd').getValue() == null ? '' : String($c.util.getComponent('cal_prtdepoEndDd').getValue())) === '') {
        await $c.win.alert("의무보유기간 만료일을 입력하십시요.");
        $c.util.getComponent("cal_prtdepoEndDd").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
    return true;
};

/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    const opener = scwin.openerScwin();
    if (await scwin.validate()) {
        if ($c.util.getComponent('dma_registerReq').get('listProcsStatCd') === "") {
            (document.stockDutyForm || { elements: [] }).target = 'stockDutyWin';
            (document.stockDutyForm || { elements: [] }).action = "stockDutyPopup.do";
            $c.util.getComponent('dma_registerReq').set('method', "insertStockDuty");
            await scwin.tx_fn_register();
        } else {
            (document.stockDutyForm || { elements: [] }).target = 'stockDutyWin';
            (document.stockDutyForm || { elements: [] }).action = "stockDutyPopup.do";
            $c.util.getComponent('dma_registerReq').set('method', "updateStockDuty");
            await scwin.tx_fn_register();
        }
    }
};

/**
 * @method
 * @name deleteRegisterReq
 * @description delete Register Req 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteRegisterReq = async function () {
    const opener = scwin.openerScwin();
    (document.stockDutyForm || { elements: [] }).target = 'stockDutyWin';
    (document.stockDutyForm || { elements: [] }).action = "stockDutyPopup.do";
    $c.util.getComponent('dma_registerReq').set('method', "deleteStockDuty");
    await scwin.tx_fn_delete();
    opener.calcelYn = 'N';
};

/**
 * @method
 * @name cancel
 * @description cancel 처리
 * @returns {void}
 * @hidden N
 */
scwin.cancel = function () {
    const opener = scwin.openerScwin();
    opener.calcelYn = 'Y';
    $c.win.closePopup();
};

/**
 * @method
 * @name close
 * @description close 처리
 * @returns {void}
 * @hidden N
 */
scwin.close = function () {
    const opener = scwin.openerScwin();
    opener.calcelYn = 'N';
    $c.win.closePopup();
};

/**
 * @method
 * @name selectChange
 * @description select Change 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selectChange = async function (e) {
    const index = $c.util.getComponent('slc_prtdepoIdSelect').getValue();
    (console.error('[sdd] 이 화면 문서에 #stkoptDutyHdInputTpNm 가 없다 — html() 무동작(as-is 는 공용 템플릿·소거된 요소를 잡았다)'), $("#stkoptDutyHdInputTpNm")).html(stockDutyarr[index].stkoptDutyHdInputTpNm);
    (console.error('[sdd] 이 화면 문서에 #prtdepoPrnTpNm 가 없다 — html() 무동작(as-is 는 공용 템플릿·소거된 요소를 잡았다)'), $("#prtdepoPrnTpNm")).html(stockDutyarr[index].prtdepoPrnTpNm);
    $("#nm").html(stockDutyarr[index].nm);
    $("#encrypResdbzRegNo").html(stockDutyarr[index].encrypResdbzRegNo);
    $("#stkoptDutyResolDd").html(dateFormat(stockDutyarr[index].stkoptDutyResolDd));
    $("#stkoptDutyTotGrntShrs").html($c.num.formatNumber(stockDutyarr[index].stkoptDutyTotGrntShrs) + "주");
    (console.error('[sdd] 이 화면 문서에 #prtdepoObjKindNm 가 없다 — html() 무동작(as-is 는 공용 템플릿·소거된 요소를 잡았다)'), $("#prtdepoObjKindNm")).html(stockDutyarr[index].prtdepoObjKindNm);
    $("#stkoptDutyExerStartDd").html(dateFormat(stockDutyarr[index].stkoptDutyExerStartDd) + "~" + dateFormat(stockDutyarr[index].stkoptDutyExerEndDd));
    $("#prtdepoEndDd").html(dateFormat(stockDutyarr[index].prtdepoEndDd));
    $c.util.getComponent("ipt_bzProcsNo").setValue(stockDutyarr[index].bzProcsNo);
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('prtdepoId', stockDutyarr[index].prtdepoId) : console.warn('[sdd] hiddenStore 부재: prtdepoId'));
    fn_selectStockDutyExer(stockDutyarr[index].bzProcsNo, stockDutyarr[index].prtdepoId);
    resultShrs = stockDutyarr[index].stkoptDutyTotGrntShrs;
    if (nowDate > dateFormat(stockDutyarr[index].prtdepoEndDd)) {
        $("#addRow").hide();
        $("#register").hide();
        await $c.win.alert("의무보유기간이 만료 되었습니다.");
    } else {
        $("#addRow").show();
        $("#register").show();
    }
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
